(r\in Z)[X:=Y]=
\begin{cases}
r\in Y,&Z=X,\\
r\in Z,&Z\ne X,
\end{cases}

C[X:=Y]=
\begin{cases}
C,&Z=X,\\
\forall Z(A[X:=Y]),&Z\ne X\land Z\ne Y,\\
\forall W((A[Z:=W])[X:=Y]),&Z\ne X\land Z=Y,
\end{cases}
